-- Phase 6 metrics: statement-snapshot owner and fleet read contracts.

create function app.gym_live_members(p_tenant_id uuid, p_local_today date)
returns jsonb language sql stable security invoker set search_path = '' as $fn$
  with q as (select ms.id, ms.member_id, ms.status, ms.starts_on, ms.ends_on from public.memberships ms where p_local_today is not null and ms.tenant_id=p_tenant_id and ms.status in ('active'::public.membership_status,'frozen'::public.membership_status) and ms.starts_on is not null and ms.ends_on is not null and ms.starts_on<=p_local_today and ms.ends_on>=p_local_today),
  r as (select q.member_id, jsonb_build_object('membershipId',q.id,'status',q.status,'startsOn',q.starts_on,'endsOn',q.ends_on,'pauses',coalesce((select jsonb_agg(jsonb_build_object('pauseId',p.id,'startsOn',p.starts_on,'endsOn',p.ends_on) order by p.id) from public.membership_pauses p where p.tenant_id=p_tenant_id and p.membership_id=q.id and p.approved_at is not null and p.rejected_at is null and p.starts_on<=p_local_today and p.ends_on>=p_local_today),'[]'::jsonb)) x from q),
  m as (select m.id,m.full_name,jsonb_agg(r.x order by (r.x->>'membershipId')::uuid) xs from r join public.members m on m.tenant_id=p_tenant_id and m.id=r.member_id group by m.id,m.full_name)
  select case when p_local_today is null then null else coalesce(jsonb_agg(jsonb_build_object('memberId',id,'memberName',full_name,'memberships',xs,'paused',exists(select 1 from jsonb_array_elements(xs) y where jsonb_array_length(y->'pauses')>0)) order by id),'[]'::jsonb) end from m
$fn$;

create function app.gym_case_rows(p_tenant_id uuid,p_as_of timestamptz)
returns jsonb language sql stable security invoker set search_path = '' as $fn$
  select coalesce(jsonb_agg(jsonb_build_object('caseId',c.id,'memberId',c.member_id,'memberName',m.full_name,'status',c.status,'nextFollowUpAt',c.next_follow_up_at,'due',c.next_follow_up_at is not null and c.next_follow_up_at<=p_as_of) order by c.id),'[]'::jsonb) from public.no_show_cases c join public.members m on m.tenant_id=c.tenant_id and m.id=c.member_id where c.tenant_id=p_tenant_id and c.status in ('open'::public.no_show_case_status,'contacted'::public.no_show_case_status,'follow_up_due'::public.no_show_case_status)
$fn$;

create function app.gym_readiness(p_tenant_id uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $fn$
declare o public.organizations%rowtype; s public.organization_settings%rowtype; missing text[]:=array[]::text[]; owner_ok boolean; has_settings boolean;
begin
 if auth.uid() is null or not(app.is_platform() or (app.current_tenant_id()=p_tenant_id and (app.is_staff() or (app.current_app_role()='gym_owner' and app.current_impersonation_id() is not null)))) then return null; end if;
 select * into o from public.organizations where id=p_tenant_id; if not found then return null; end if;
 select * into s from public.organization_settings where tenant_id=p_tenant_id; has_settings:=found; if not has_settings then missing:=array_append(missing,'settings'); end if;
 if (select count(*) from public.branches b where b.tenant_id=p_tenant_id and b.is_default)<>1 then missing:=array_append(missing,'default_branch'); end if;
 select exists(select 1 from public.staff st join auth.users u on u.id=st.user_id where st.tenant_id=p_tenant_id and st.role='gym_owner'::public.app_role and st.is_active and not exists(select 1 from public.platform_users pu where pu.user_id=u.id)) into owner_ok;
 if not owner_ok then missing:=array_append(missing,'owner_access'); end if;
 if not exists(select 1 from pg_catalog.pg_timezone_names z where z.name=o.timezone) then missing:=array_append(missing,'timezone'); end if; if o.currency<>'INR' then missing:=array_append(missing,'currency'); end if;
 if has_settings then
  if s.no_show_threshold_days<=0 then missing:=array_append(missing,'no_show_threshold'); end if; if s.streak_rule_type not in ('visit_streak'::public.streak_rule_type,'weekly_goal'::public.streak_rule_type,'calendar_streak'::public.streak_rule_type) then missing:=array_append(missing,'streak_rule'); end if; if s.weekly_goal_default not between 1 and 14 then missing:=array_append(missing,'weekly_goal'); end if; if s.checkin_dedupe_seconds<0 then missing:=array_append(missing,'checkin_window'); end if; if s.grace_period_days<0 then missing:=array_append(missing,'grace_period'); end if; if s.max_freeze_days_per_year<0 then missing:=array_append(missing,'freeze_limit'); end if; if not exists(select 1 from public.staff st where st.tenant_id=p_tenant_id and st.role=s.pause_approver_role and st.is_active) then missing:=array_append(missing,'pause_approver'); end if;
 end if;
 return jsonb_build_object('settingsComplete',cardinality(missing)=0,'missingSettings',to_jsonb(missing),'ownerAccessPending',not owner_ok,'providerReadiness',jsonb_build_object('push',jsonb_build_object('ready',false,'reason','provider_unconfigured'),'sms',jsonb_build_object('ready',false,'reason','outside_v1'),'email',jsonb_build_object('ready',false,'reason','outside_v1'),'whatsappBusiness',jsonb_build_object('ready',false,'reason','outside_v1')));
end $fn$;

create function app.gym_metrics(p_tenant_id uuid,p_as_of timestamptz,p_from date,p_through date)
returns jsonb language plpgsql stable security invoker set search_path = '' as $fn$
declare tz text; today date; fd date; td date; starts_at timestamptz; ends_before timestamptz; mode text; live jsonb; cases jsonb; result jsonb;
begin
 if (p_from is null)<>(p_through is null) or (p_from is not null and p_from>p_through) then raise exception 'Invalid metrics range' using errcode='22023',detail='invalid_metrics_range'; end if;
 select timezone into tz from public.organizations where id=p_tenant_id; if not found then return null; end if; if not exists(select 1 from pg_catalog.pg_timezone_names z where z.name=tz) then raise exception 'Invalid gym timezone' using errcode='22023',detail='invalid_gym_timezone'; end if;
 today:=(p_as_of at time zone tz)::date; mode:=case when p_from is null then 'month_to_date' else 'explicit' end; fd:=coalesce(p_from,date_trunc('month',today)::date); td:=coalesce(p_through,today); starts_at:=fd::timestamp at time zone tz; ends_before:=case when p_from is null then p_as_of else (td+1)::timestamp at time zone tz end; live:=app.gym_live_members(p_tenant_id,today); cases:=app.gym_case_rows(p_tenant_id,p_as_of);
 with visits as (select jsonb_build_object('attendanceId',a.id,'memberId',a.member_id,'memberName',m.full_name,'checkedInAt',a.checked_in_at) x from public.attendance a join public.members m on m.tenant_id=a.tenant_id and m.id=a.member_id where a.tenant_id=p_tenant_id and a.checked_in_at>=today::timestamp at time zone tz and a.checked_in_at<(today+1)::timestamp at time zone tz), recoveries as (select jsonb_build_object('caseId',c.id,'memberId',c.member_id,'memberName',m.full_name,'returnedAt',c.returned_at) x from public.no_show_cases c join public.members m on m.tenant_id=c.tenant_id and m.id=c.member_id where c.tenant_id=p_tenant_id and c.returned_at>=starts_at and c.returned_at<ends_before), collected as (select jsonb_build_object('paymentId',p.id,'memberId',p.member_id,'memberName',m.full_name,'amountPaise',p.amount_paise::text,'currency',p.currency,'paidAt',p.paid_at,'receiptNumber',p.receipt_number,'addonOrderId',ao.id) x from public.payments p join public.members m on m.tenant_id=p.tenant_id and m.id=p.member_id left join public.addon_orders ao on ao.tenant_id=p.tenant_id and ao.payment_id=p.id where p.tenant_id=p_tenant_id and p.status in ('paid'::public.payment_status,'refunded'::public.payment_status,'reversed'::public.payment_status) and p.paid_at>=starts_at and p.paid_at<ends_before), returned as (select jsonb_build_object('refundId',r.id,'paymentId',r.payment_id,'memberId',p.member_id,'memberName',m.full_name,'amountPaise',r.amount_paise::text,'currency',r.currency,'kind',r.kind,'processedAt',r.processed_at,'addonOrderId',ao.id) x from public.refunds r join public.payments p on p.tenant_id=r.tenant_id and p.id=r.payment_id join public.members m on m.tenant_id=p.tenant_id and m.id=p.member_id left join public.addon_orders ao on ao.tenant_id=p.tenant_id and ao.payment_id=p.id where r.tenant_id=p_tenant_id and r.status='completed'::public.refund_status and r.processed_at>=starts_at and r.processed_at<ends_before), renewals as (select app.membership_renewal_remainder(p_tenant_id,ms.id)||jsonb_build_object('memberName',m.full_name) x from public.memberships ms join public.members m on m.tenant_id=ms.tenant_id and m.id=ms.member_id where ms.tenant_id=p_tenant_id and ms.ends_on between fd and td), leads as (select jsonb_build_object('leadId',l.id,'fullName',l.full_name,'createdAt',l.created_at,'stage',l.stage,'convertedMemberId',l.converted_member_id,'convertedAt',l.converted_at,'converted',l.stage='converted'::public.lead_stage) x from public.leads l where l.tenant_id=p_tenant_id and l.created_at>=starts_at and l.created_at<ends_before), ptb as (select o.*,case when o.total_paise>0 then p.paid_at else o.sold_at end cohort_at,case when o.total_paise>0 then 'payment' else 'complimentary_sale' end source from public.addon_orders o join public.addon_products ap on ap.tenant_id=o.tenant_id and ap.id=o.addon_product_id and ap.kind='pt_package'::public.addon_kind left join public.payments p on p.tenant_id=o.tenant_id and p.id=o.payment_id where o.tenant_id=p_tenant_id and o.status in ('paid'::public.addon_order_status,'active'::public.addon_order_status,'completed'::public.addon_order_status) and (o.total_paise=0 or coalesce((select sum(r.amount_paise)::numeric from public.refunds r where r.tenant_id=o.tenant_id and r.payment_id=o.payment_id and r.status='completed'::public.refund_status),0::numeric)<o.total_paise::numeric)), pt as (select jsonb_build_object('orderId',q.id,'memberId',q.member_id,'memberName',m.full_name,'productId',q.addon_product_id,'trainerStaffId',q.trainer_staff_id,'status',q.status,'cohortAt',q.cohort_at,'cohortSource',q.source,'sessionsUsed',q.sessions_used::text,'sessionsTotal',q.sessions_total::text) x from ptb q join public.members m on m.tenant_id=q.tenant_id and m.id=q.member_id where q.sessions_total is not null and q.cohort_at>=starts_at and q.cohort_at<ends_before)
 select jsonb_build_object('tenantId',p_tenant_id,'asOf',p_as_of,'timezone',tz,'localToday',today,'range',jsonb_build_object('from',fd,'through',td,'startsAt',starts_at,'endsBefore',ends_before,'mode',mode),'cards',jsonb_build_object('visitsToday',(select count(*)::text from visits),'liveMembers',jsonb_array_length(live)::text,'pausedMembers',(select count(*)::text from jsonb_array_elements(live) y where (y->>'paused')::boolean),'openCases',jsonb_array_length(cases)::text,'followUpsDue',(select count(*)::text from jsonb_array_elements(cases) y where (y->>'due')::boolean),'recovered',(select count(*)::text from recoveries),'cash',coalesce((select jsonb_agg(jsonb_build_object('currency',currency,'collectedPaise',co::text,'returnedPaise',re::text,'netPaise',(co-re)::text) order by currency) from(select currency,sum(co)::numeric co,sum(re)::numeric re from(select x->>'currency' currency,(x->>'amountPaise')::numeric co,0::numeric re from collected union all select x->>'currency',0::numeric,(x->>'amountPaise')::numeric from returned) a group by currency)b),'[]'::jsonb),'renewal',coalesce((select jsonb_agg(jsonb_build_object('currency',currency,'duePaise',due::text) order by currency) from(select x->>'currency' currency,sum((x->>'duePaise')::numeric) due from renewals group by x->>'currency')a),'[]'::jsonb),'leads',jsonb_build_object('converted',(select count(*) filter(where(x->>'converted')::boolean)::text from leads),'total',(select count(*)::text from leads)),'addonCash',coalesce((select jsonb_agg(jsonb_build_object('currency',currency,'collectedPaise',co::text,'returnedPaise',re::text,'netPaise',(co-re)::text) order by currency) from(select currency,sum(co)::numeric co,sum(re)::numeric re from(select x->>'currency' currency,(x->>'amountPaise')::numeric co,0::numeric re from collected where x->>'addonOrderId' is not null union all select x->>'currency',0::numeric,(x->>'amountPaise')::numeric from returned where x->>'addonOrderId' is not null)a group by currency)b),'[]'::jsonb),'pt',jsonb_build_object('sessionsUsed',coalesce((select sum((x->>'sessionsUsed')::numeric)::text from pt),'0'),'sessionsTotal',coalesce((select sum((x->>'sessionsTotal')::numeric)::text from pt),'0'),'orders',(select count(*)::text from pt))),'components',jsonb_build_object('visits',coalesce((select jsonb_agg(x order by(x->>'attendanceId')::uuid)from visits),'[]'::jsonb),'liveMembers',live,'cases',cases,'recoveries',coalesce((select jsonb_agg(x order by(x->>'caseId')::uuid)from recoveries),'[]'::jsonb),'collected',coalesce((select jsonb_agg(x order by(x->>'paymentId')::uuid)from collected),'[]'::jsonb),'returned',coalesce((select jsonb_agg(x order by(x->>'refundId')::uuid)from returned),'[]'::jsonb),'renewals',coalesce((select jsonb_agg(x order by(x->>'membershipId')::uuid)from renewals),'[]'::jsonb),'leads',coalesce((select jsonb_agg(x order by(x->>'leadId')::uuid)from leads),'[]'::jsonb),'ptOrders',coalesce((select jsonb_agg(x order by(x->>'orderId')::uuid)from pt),'[]'::jsonb)),'warnings',jsonb_build_object('undatedPayments',coalesce((select jsonb_agg(jsonb_build_object('paymentId',p.id,'amountPaise',p.amount_paise::text,'currency',p.currency)order by p.id)from public.payments p where p.tenant_id=p_tenant_id and p.status in ('paid'::public.payment_status,'refunded'::public.payment_status,'reversed'::public.payment_status)and p.paid_at is null),'[]'::jsonb),'undatedReturns',coalesce((select jsonb_agg(jsonb_build_object('refundId',r.id,'paymentId',r.payment_id,'amountPaise',r.amount_paise::text,'currency',r.currency)order by r.id)from public.refunds r where r.tenant_id=p_tenant_id and r.status='completed'::public.refund_status and r.processed_at is null),'[]'::jsonb),'undatedPtOrders',coalesce((select jsonb_agg(jsonb_build_object('orderId',q.id,'status',q.status)order by q.id)from ptb q where q.cohort_at is null),'[]'::jsonb),'incompletePtOrders',coalesce((select jsonb_agg(jsonb_build_object('orderId',q.id,'status',q.status,'cohortAt',q.cohort_at,'sessionsUsed',q.sessions_used::text,'sessionsTotal',null)order by q.id)from ptb q where q.sessions_total is null),'[]'::jsonb))) into result; return result;
end $fn$;

create function public.owner_metrics(p_from date default null,p_through date default null) returns jsonb language plpgsql stable security invoker set search_path='' as $fn$ begin if (p_from is null)<>(p_through is null) or (p_from is not null and p_from>p_through) then raise exception 'Invalid metrics range' using errcode='22023',detail='invalid_metrics_range'; end if; if auth.uid() is null or app.current_tenant_id() is null or app.current_impersonation_id() is not null or not(app.is_staff() and app.current_app_role() in ('gym_owner','gym_manager')) then raise exception 'Not permitted to read owner metrics' using errcode='42501'; end if; return app.gym_metrics(app.current_tenant_id(),statement_timestamp(),p_from,p_through); end $fn$;

create function public.fleet_metrics() returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare ts timestamptz:=statement_timestamp(); begin if auth.uid() is null or app.is_platform() is not true then raise exception 'Not permitted to read fleet metrics' using errcode='42501'; end if; return (with g as(select o.*,app.gym_readiness(o.id) ready,case when exists(select 1 from pg_catalog.pg_timezone_names z where z.name=o.timezone) then app.gym_live_members(o.id,(ts at time zone o.timezone)::date) else null end live,app.gym_case_rows(o.id,ts) cases,coalesce((select jsonb_agg(jsonb_build_object('notificationId',n.id,'memberId',n.member_id,'channel',n.channel,'failedAt',n.failed_at,'failedReason',n.failed_reason)order by n.id)from public.notifications n where n.tenant_id=o.id and n.status='failed'::public.notification_status),'[]'::jsonb) failed from public.organizations o), r as(select jsonb_build_object('tenantId',id,'name',name,'gymCode',gym_code,'status',status,'tier',tier,'timezone',timezone,'trialEndsAt',trial_ends_at,'activeMembers',case when live is null then null else jsonb_array_length(live)::text end,'openCases',jsonb_array_length(cases)::text,'failedNotifications',jsonb_array_length(failed)::text,'settingsComplete',ready->'settingsComplete','missingSettings',ready->'missingSettings','ownerAccessPending',ready->'ownerAccessPending','providerReadiness',ready->'providerReadiness','metricsError',case when live is null then jsonb_build_object('code','invalid_gym_timezone') else null end,'components',jsonb_build_object('liveMembers',live,'cases',cases,'failedNotifications',failed)) x from g), a as(select coalesce(jsonb_agg(x order by x->>'name',(x->>'tenantId')::uuid),'[]'::jsonb) gyms from r) select jsonb_build_object('asOf',ts,'gyms',gyms,'exceptions',jsonb_build_object('settingsIncomplete',coalesce((select jsonb_agg((x->>'tenantId')::uuid order by(x->>'tenantId')::uuid)from jsonb_array_elements(gyms)x where not(x->>'settingsComplete')::boolean),'[]'::jsonb),'ownerAccessPending',coalesce((select jsonb_agg((x->>'tenantId')::uuid order by(x->>'tenantId')::uuid)from jsonb_array_elements(gyms)x where(x->>'ownerAccessPending')::boolean),'[]'::jsonb),'providerUnavailable',coalesce((select jsonb_agg((x->>'tenantId')::uuid order by(x->>'tenantId')::uuid)from jsonb_array_elements(gyms)x),'[]'::jsonb),'trialExpired',coalesce((select jsonb_agg((x->>'tenantId')::uuid order by(x->>'tenantId')::uuid)from jsonb_array_elements(gyms)x where x->>'status'='trial' and((x->>'trialEndsAt')is null or(x->>'trialEndsAt')::timestamptz<=ts)),'[]'::jsonb)))from a); end $fn$;

revoke all on function app.gym_live_members(uuid,date),app.gym_case_rows(uuid,timestamptz),app.gym_metrics(uuid,timestamptz,date,date),app.gym_readiness(uuid) from public,anon;
grant execute on function app.gym_live_members(uuid,date),app.gym_case_rows(uuid,timestamptz),app.gym_metrics(uuid,timestamptz,date,date),app.gym_readiness(uuid) to authenticated,service_role;
revoke all on function public.owner_metrics(date,date),public.fleet_metrics() from public,anon,service_role;
grant execute on function public.owner_metrics(date,date),public.fleet_metrics() to authenticated;
